* {
  box-sizing: border-box;
}
.responsive {
  padding: 0 6px;
  float: left;
  width: 24.99999%;
}
div.gallery {
  border: 1px solid #ccc;
}

@media only screen and (max-width: 700px) {
  .responsive {
    width: 49.99999%;
  }
}
@media only screen and (max-width: 500px) {
  .responsive {
    width: 100%;
  }
}
